import {writeFileSync,mkdirSync} from 'node:fs';
import {launchBrowser} from '../tools/browser-pool/client.ts';
import {readFixture} from '../tools/qa/fixture-io.ts';
import {loadFixtureInPage} from '../tools/qa/load-fixture.ts';
const tier=process.env.QUALITY||'high',out=`test-results/s103-focused-${tier}`;mkdirSync(out,{recursive:true});
const b=await launchBrowser({headless:true,args:['--use-angle=metal','--enable-gpu','--ignore-gpu-blocklist']});
try{const p=await b.newPage({viewport:{width:1280,height:720}});let errors=[];p.on('pageerror',e=>errors.push(String(e)));await p.goto(`http://127.0.0.1:4931/?testApi=1&scenelab=1&renderer=webgl&audio=muted&dpr=1&quality=${tier}`);await p.waitForFunction(()=>!!window.__SS__,null,{timeout:180000});
await loadFixtureInPage(p,readFixture('tests/fixtures/saves/qa/l10-dispersal-console.json.gz'));
await p.evaluate(t=>{const a=window.__SS__,g=window.__SCENE__.game;a.settings.set({quality:t});a.cheats.god(true);a.camera.follow();const c=g.world.missions.def.anchors['cure-console'];a.teleport('player',c);},tier);
let samples=[];
for(const zoom of [1,1.5]){await p.evaluate(async z=>{let a=window.__SS__;a.camera.zoom(z);await a.screenshotReady();window.__qa={frames:[],rows:[],active:true};let prev;function frame(t){if(!window.__qa.active)return;let g=window.__SCENE__.game,w=g.world,q=window.__qa;if(prev&& !g.clock.paused&&!g.loading)q.frames.push(t-prev);prev=t;let svc=w.l10Encounters?.state?.finaleEntry,boss=w.megaPursuit?.entity();q.rows.push({tick:w.tick,boss:boss&&{id:boss.id,...boss.transform,hp:boss.health.current,mode:w.megaPursuit.state.mode},service:svc&&{ids:svc.ids,walking:svc.walking,actors:svc.ids.map(id=>{let e=w.entities.get(id);return e&&{id,...e.transform,hp:e.health.current,hidden:e.infected?.hidden,state:e.infected?.state}})}});requestAnimationFrame(frame)}requestAnimationFrame(frame);a.resume();},zoom);await p.keyboard.press('e');await p.waitForTimeout(32000);await p.evaluate(()=>{window.__SS__.pause();window.__qa.active=false});await p.screenshot({path:`${out}/z${zoom}.jpg`,type:'jpeg',quality:80});samples.push({zoom,...await p.evaluate(()=>window.__qa)});}
// Assisted end-state coverage: ordinary damage pipeline kills the boss; no mission flags changed.
const before=await p.evaluate(()=>{let w=window.__SCENE__.game.world;return structuredClone(w.missions.state)});
await p.evaluate(()=>{let w=window.__SCENE__.game.world,e=w.megaPursuit.entity();for(let i=0;i<20&&e.health.current>0;i++)w.combat.damage.apply({sourceId:1,targetId:e.id,attackId:10000+i,actionId:'weapon.rocket-launcher',direct:true,origin:w.entities.get(1).transform,direction:{x:1,z:0},base:10000,multiplier:1,type:'explosive',stagger:0,knockback:0});});await p.evaluate(()=>window.__SS__.step(120));await p.keyboard.down('e');await p.evaluate(()=>window.__SS__.step(2));await p.keyboard.up('e');await p.evaluate(()=>window.__SS__.step(60));const released=await p.evaluate(()=>structuredClone(window.__SCENE__.game.world.missions.state));await p.screenshot({path:`${out}/release.jpg`,type:'jpeg',quality:80});await p.evaluate(()=>window.__SS__.step(900));const ending=await p.evaluate(()=>structuredClone(window.__SCENE__.game.world.missions.state));await p.screenshot({path:`${out}/epilogue.jpg`,type:'jpeg',quality:80});writeFileSync(`${out}/evidence.json`,JSON.stringify({tier,errors,samples,before,released,ending}));console.log(JSON.stringify({tier,errors,frames:samples.map(s=>({zoom:s.zoom,n:s.frames.length,p95:s.frames.sort((a,b)=>a-b)[Math.floor(s.frames.length*.95)]})),released:released.states['cure-released'],epilogue:ending.epilogue}));
}finally{await b.close()}

